use super::prelude::*;

/// Shiv. Cost 0, EXHAUST. Deal 4 damage.
///
/// Any enchantment on the Shiv contributes generically: the
/// `modify_damage` pipeline now applies the enchantment additive term
/// (`hooks::modify_damage` reads the played card's enchantments — bead
/// `sts2-rs-enchant-damage-additive`), so the Shiv only needs to fire
/// [`crate::enchantments::apply_enchantment_on_play`] for any on-play
/// side-effect. The Shiv is always played as a powered attack, so the
/// enchantment additive (`IsPoweredAttack`) applies. The sole enchantment in
/// play today is [`EnchantmentId::Inky`] (every Blade-of-Ink Shiv — C#
/// `BladeOfInk.cs:36`), which adds `+2` damage and applies `1` Weak.
pub(crate) fn play_shiv(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    use crate::enchantments::apply_enchantment_on_play;

    let Some(active) = sts2_core::card_effects::resolving_card_uid(state) else {
        return EffectResult::Resolved;
    };
    let damage = current_damage(state);

    // C# `Shiv.OnPlay` (Shiv.cs:60-72): while the player has FanOfKnives the
    // attack is `TargetingAllOpponents` (every enemy) and the card's dynamic
    // `TargetType` is `AllEnemies` (Shiv.cs:23-32) — no per-enemy target is
    // surfaced; otherwise it is a single `AnyEnemy` hit on `cardPlay.Target`.
    // Mirror both arms so the FanOfKnives AoE matches the untargeted legal
    // action the engine emits for a Shiv under FanOfKnives.
    //
    // GH #335: the AoE arm also catches a `target: None` play whose FanOfKnives
    // has lapsed between the moment the untargeted action was surfaced/accepted
    // (`cards::effective_target_type`) and now. That arm is what produced the
    // untargeted play, so resolving it is the faithful completion; the previous
    // `target.expect(..)` turned the disagreement into a process-killing panic
    // (a PyO3 `PanicException` is a `BaseException`, so it escapes the Python
    // worker guards and takes the whole worker down).
    let single_target = if sts2_core::cards::shiv_hits_all_enemies(state) {
        None
    } else {
        target
    };
    let Some(t) = single_target else {
        let card = sts2_core::card_effects::originating_card_id(state);
        let _ = sts2_core::card_effects::deal_damage_to_all_alive_enemies(
            state,
            damage,
            sts2_core::hooks::ValueProps::MOVE,
            card,
        );
        // `Inky.OnPlay` runs after the attack and reads
        // `CombatState.HittableEnemies` then (Inky.cs, `AllEnemies` arm), so
        // enemies the attack killed are skipped and enemies its kills spawned
        // (Infested's Wrigglers) are included.
        let targets: Vec<CreatureUid> = state
            .enemy_uids
            .iter()
            .copied()
            .filter(|uid| {
                state
                    .creatures
                    .iter()
                    .any(|c| c.id == uid.0 && c.current_hp > 0)
            })
            .collect();
        for uid in targets {
            apply_enchantment_on_play(state, active, uid);
        }
        return EffectResult::Resolved;
    };

    let _ = deal_damage_player_to_enemy(state, t, damage);
    apply_enchantment_on_play(state, active, t);
    EffectResult::Resolved
}
